import{_ as p,a0 as r,w as l,s as d,I as n,x as t,a1 as o,A as i,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux中，創建聊天服務器、移除冗餘軟件包的實用命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中，創建聊天服務器、移除冗餘軟件包的實用命令 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中，創建聊天服務器、移除冗餘軟件包的實用命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中，創建聊天服務器、移除冗餘軟件包的實用命令 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150504 Useful Commands to Create Commandline Chat Server and Remove Unwanted Packages in Linux","title":"Linux中，創建聊天服務器、移除冗餘軟件包的實用命令","tag":"201506","desc":""},"relativePath":"201506/20150504 Useful Commands to Create Commandline Chat Server and Remove Unwanted Packages in Linux.md","filePath":"[post].md"}'),c={name:"201506/20150504 Useful Commands to Create Commandline Chat Server and Remove Unwanted Packages in Linux.md"};function u(m,e,g,w,x,f){const a=r("Link");return l(),d("div",null,[e[14]||(e[14]=n("h1",{id:"linux中-創建聊天服務器、移除冗餘軟件包的實用命令",tabindex:"-1"},[t("Linux中，創建聊天服務器、移除冗餘軟件包的實用命令 "),n("a",{class:"header-anchor",href:"#linux中-創建聊天服務器、移除冗餘軟件包的實用命令","aria-label":"Permalink to “Linux中，創建聊天服務器、移除冗餘軟件包的實用命令”"},"​")],-1)),e[15]||(e[15]=n("p",null,"這裏,我們來看Linux命令列實用技巧的下一個部分。如果你錯過了Linux Tracks之前的文章，可以從這裏找到。",-1)),n("ul",null,[n("li",null,[o(a,{href:"https://linux.cn/article-5485-1.html"},{default:i(()=>[...e[0]||(e[0]=[t("5個有趣的Linux命令列技巧",-1)])]),_:1})])]),e[16]||(e[16]=s(`<p>本篇中，我們將會介紹6個命令列小技巧，包括使用Netcat命令創建Linux命令列聊天，從某個命令的輸出中對某一列做加法，移除Debian和CentOS上多餘的包，從命令列中獲取本地與遠程的IP地址，在終端獲得彩色的輸出與解碼各樣的顏色，最後是Linux命令列裏井號標籤的使用。讓我們來一個一個地看一下。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/linux-commandline-chat-server.jpg" alt="Linux Commandline Chat Server"></p><p><em>6個實用的命令列技巧</em></p><h3 id="_1-創建linux命令列聊天服務" tabindex="-1">1. 創建Linux命令列聊天服務 <a class="header-anchor" href="#_1-創建linux命令列聊天服務" aria-label="Permalink to “1. 創建Linux命令列聊天服務”">​</a></h3><p>我們大家使用聊天服務都有很長一段時間了。對於Google Chat，Hangout，Facebook Chat，Whatsapp，Hike和其他一些應用與集成的聊天服務，我們都很熟悉了。那你知道Linux的nc命令可以使你的Linux機器變成一個聊天服務器，而僅僅只需要一行命令嗎。什麼是nc命令，它又是怎麼工作的呢？</p><p>nc即Linux netcat命令。nc就像瑞士軍刀一樣，內建了大量的功能。nc可用做調式工具，調查工具，使用TCP/UDP讀寫網絡連接，DNS正向/反向查詢等等。</p><p>nc主要用在端口掃描，文件傳輸，後台和端口監聽。nc可以使用任何閒置的端口和任何本地網絡源地址。</p><p>使用nc命令（在192.168.0.7的服務器上）創建一個命令列即時信息傳輸服務器。</p><pre><code>$ nc -l -vv -p 11119
</code></pre><p>對上述命令的解釋。</p><ul><li>-v : 顯示冗餘信息</li><li>-vv : 顯示更多的冗餘信息</li><li>-p : 本地端口號</li></ul><p>你可以用任何其他的本地端口號替換11119。</p><p>接下來在客户端機器（IP地址：192.168.0.15），運行下面的命令初始化聊天會話（這裏需要上面提到的信息服務器正在運行）。</p><pre><code>$ nc 192.168.0.7:11119
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Chat-on-Linux-Commandline.gif" alt="Linux Commandline Chat with nc Command"></p><p><strong>注意</strong>：你可以按下ctrl+c終止會話，同時nc聊天是一個一對一的服務。</p><h3 id="_2-linux中如何統計某一列的總值" tabindex="-1">2. Linux中如何統計某一列的總值 <a class="header-anchor" href="#_2-linux中如何統計某一列的總值" aria-label="Permalink to “2. Linux中如何統計某一列的總值”">​</a></h3><p>如何在終端裏統計某個命令的輸出中其中一列的數值總和，</p><p>‘ls -l’命令的輸出。</p><pre><code>$ ls -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sum-Values.gif" alt="Sum Numerical Values"></p><p>注意到第二列代表軟連接的數量，第五列則是文件的大小。假設我們需要彙總第五列的數值。</p><p>僅僅列出第五列的內容。我們會使用‘awk’命令做到這點。‘$5’即代表第五列。</p><pre><code>$ ls -l | awk &#39;{print $5}&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/List-Content-Column.gif" alt="List Content Column"></p><p>現在，通過管道連接，使用awk打印出第五列數值的總和。</p><pre><code>$ ls -l | awk &#39;{print $5}&#39; | awk &#39;{total = total + $1}END{print total}&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sum-Columns.gif" alt="Sum and Print Columns"></p><h3 id="在linux裏如何移除廢棄包" tabindex="-1">在Linux裏如何移除廢棄包 <a class="header-anchor" href="#在linux裏如何移除廢棄包" aria-label="Permalink to “在Linux裏如何移除廢棄包”">​</a></h3><p>廢棄包是指那些作為其他包的依賴而被安裝，但是當源包被移除之後就不再需要的包。</p><p>假設我們安裝了一個叫gtprogram的軟件包，其依賴是gtdependency。除非我們安裝了gtdependency，否則安裝不了gtprogram。</p><p>當我們移除gtprogram的時候，默認並不會移除gtdependency。並且如果我們不移除gtdependency的話，它就會遺留下來成為廢棄包，與其他任何包再無聯繫。</p><pre><code># yum autoremove                [On RedHat Systems]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Remove-Orphan-Packages-in-CentOS1.gif" alt="Remove Orphan Packages in CentOS"></p><pre><code># apt-get autoremove                [On Debian Systems]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Remove-Orphan-Packages-in-Debian.gif" alt="Remove Orphan Packages in Debian"></p><p>你應該經常移除廢棄包，保持Linux機器僅僅加載一些需要的東西。</p><h3 id="_4-如何獲得linux服務器本地的與公網的ip地址" tabindex="-1">4. 如何獲得Linux服務器本地的與公網的IP地址 <a class="header-anchor" href="#_4-如何獲得linux服務器本地的與公網的ip地址" aria-label="Permalink to “4. 如何獲得Linux服務器本地的與公網的IP地址”">​</a></h3><p>為了獲得本地IP地址，運行下面的一行腳本。</p><pre><code>$ ifconfig | grep &quot;inet addr:&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39; | cut -f2 -d:
</code></pre><p>你必須安裝了ifconfig，如果沒有，使用apt或者yum工具安裝需要的包。這裏我們將會管道連接ifconfig的輸出，並且結合grep命令找到包含“intel addr：”的字符串。</p><p>我們知道對於輸出本地IP地址，ifconfig命令足夠用了。但是ifconfig生成了許多的輸出，而我們關注的地方僅僅是本地IP地址，不是其他的。</p><pre><code># ifconfig | grep &quot;inet addr:&quot;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-Local-IP-Address.gif" alt="Check Local IP Address"></p><p>儘管目前的輸出好多了，但是我們需要過濾出本地的IP地址，不含其他東西。針對這個，我們將會使用awk打印出第二列輸出，通過管道連接上述的腳本。</p><pre><code># ifconfig | grep “inet addr:” | awk &#39;{print $2}&#39; 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Filter-IP-Address.gif" alt="Filter Only IP Address"></p><p>上面圖片清楚的表示，我們已經很大程度上自定義了輸出，當仍然不是我們想要的。本地環路地址 127.0.0.1 仍然在結果中。</p><p>我們可以使用grep的-v選項，這樣會打印出不匹配給定參數的其他行。每個機器都有同樣的環路地址 127.0.0.1，所以使用grep -v打印出不包含127.0.0.1的行，通過管道連接前面的腳本。</p><pre><code># ifconfig | grep &quot;inet addr&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Print-IP-Address.gif" alt="Print IP Address"></p><p>我們差不多得到想要的輸出了，僅僅需要從開頭替換掉字符串<code>(addr:)</code>。我們將會使用cut命令單獨打印出第二列。一二列之間並不是用tab分割，而是<code>(:)</code>，所以我們需要使用到域分割符選項<code>(-d)</code>，通過管道連接上面的輸出。</p><pre><code># ifconfig | grep &quot;inet addr:&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39; | cut -f2 -d:
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Custome-IP-Address.gif" alt="Customized IP Address"></p><p>最後！期望的結果出來了。</p><h3 id="_5-如何在linux終端彩色輸出" tabindex="-1">5.如何在Linux終端彩色輸出 <a class="header-anchor" href="#_5-如何在linux終端彩色輸出" aria-label="Permalink to “5.如何在Linux終端彩色輸出”">​</a></h3><p>你可能在終端看見過彩色的輸出。同時你也可能知道在終端裏允許/禁用彩色輸出。如果都不知道的話，你可以參考下面的步驟。</p><p>在Linux中，每個用户都有<code>&#39;.bashrc&#39;</code>文件，被用來管理你的終端輸出。打開並且編輯該文件，用你喜歡的編輯器。注意一下，這個文件是隱藏的（文件開頭為點的代表隱藏文件）。</p><pre><code>$ vi /home/$USER/.bashrc
</code></pre><p>確保以下的行沒有被註釋掉。即，行開頭沒有#。</p><pre><code>if [ -x /usr/bin/dircolors ]; then
    test -r ~/.dircolors &amp;&amp; eval &quot;$(dircolors -b ~/.dircolors)&quot; || eval &quot;$(dirc$
    alias ls=&#39;ls --color=auto&#39;
    #alias dir=&#39;dir --color=auto&#39;
    #alias vdir=&#39;vdir --color=auto&#39;

    alias grep=&#39;grep --color=auto&#39;
    alias fgrep=&#39;fgrep --color=auto&#39;
    alias egrep=&#39;egrep --color=auto&#39;
fi
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/bashrc-file.gif" alt="User .bashrc File"></p><p>完成後！保存並退出。為了讓改動生效，需要註銷賬户後再次登錄。</p><p>現在，你會看見列出的文件和文件夾名字有着不同的顏色，根據文件類型來決定。要了解所用的顏色代碼，可以運行下面的命令。</p><pre><code>$ dircolors -p | less
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Linux-Color-Output.gif" alt="Linux Color Output"></p><h3 id="_6-如何用-號標記linux命令和腳本" tabindex="-1">6.如何用#號標記Linux命令和腳本 <a class="header-anchor" href="#_6-如何用-號標記linux命令和腳本" aria-label="Permalink to “6.如何用#號標記Linux命令和腳本”">​</a></h3><p>我們一直在Twitter，Facebook和Google Plus（可能是其他我們沒有提到的地方）上使用#號標籤。那些#號標籤使得其他人搜索一個標籤更加容易。可是很少人知道，我們可以在Linux命令列使用#號標籤。</p><p>我們已經知道配置文件裏的<code>#</code>，在大多數的編程語言中，這個符號被用作註釋行，即不被執行。</p><p>運行一個命令，然後為這個命令創建一個#號標籤，這樣之後我們就可以找到它。假設我們有一個很長的腳本，就上面第四點被執行的命令。現在為它創建一個#號標籤。我們知道ifconfig可以被sudo或者root執行，因此用root來執行。</p><pre><code># ifconfig | grep &quot;inet addr:&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39; | cut -f2 -d: #myip
</code></pre><p>上述腳本被’myip‘給標記了。現在在reverse-i-search（按下ctrl+r）搜索一下這個標籤，在終端裏，並輸入’myip‘。你可以從這裏開始執行。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-Command-Hash-Tags.gif" alt="Create Command Hash Tags"></p><p>你可以為每個命令創建#號標籤，之後使用reverse-i-search找到它。</p><p>目前就這麼多了。我們一直在辛苦的工作，創造有趣的，有知識性的內容給你。你覺得我們是如何工作的呢？歡迎諮詢任何問題。你可以在下面評論。保持聯絡！Kudox。</p><hr>`,76)),n("p",null,[e[2]||(e[2]=t("via: ",-1)),o(a,{href:"http://www.tecmint.com/linux-commandline-chat-server-and-remove-unwanted-packages/"},{default:i(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/linux-commandline-chat-server-and-remove-unwanted-packages/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),o(a,{href:"http://www.tecmint.com/author/avishek/"},{default:i(()=>[...e[3]||(e[3]=[t("Avishek Kumar",-1)])]),_:1}),e[7]||(e[7]=t(" 譯者：",-1)),o(a,{href:"https://github.com/wi-cuckoo"},{default:i(()=>[...e[4]||(e[4]=[t("wi-cuckoo",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),o(a,{href:"http://linux.cn/"},{default:i(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const v=p(c,[["render",u]]);export{L as __pageData,v as default};
